/**
 * Validate the real CodeQL workflow and reject unsafe semantic YAML mutations.
 *
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - variable workflowURL: line 19
 * - variable matrixExpression: line 20
 * - function record: line 23
 * - function assertPolicy: line 29
 * - variable mutations: line 85
 * @@SYMBOL_INDEX_END
 */

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { describe, expect, it } from "vitest";
import { parse } from "yaml";

const workflowURL = new URL("../../.github/workflows/codeql.yml", import.meta.url);
const matrixExpression = "${{ matrix.language }}";

/** Narrow parsed YAML to a mapping before inspecting security authority. */
function record(value: unknown): Record<string, unknown> {
  assert(value !== null && typeof value === "object" && !Array.isArray(value));
  return value as Record<string, unknown>;
}

/** Enforce source coverage, safe event routing and upload-only job authority. */
function assertPolicy(value: unknown): void {
  const workflow = record(value);
  expect(Object.keys(workflow).sort()).toEqual(
    ["name", "on", "permissions", "concurrency", "jobs"].sort(),
  );
  expect(workflow["name"]).toBe("CodeQL");
  expect(workflow["on"]).toStrictEqual({
    push: { branches: ["main"] },
    pull_request: { branches: ["main"] },
    schedule: [{ cron: "23 7 * * 2" }],
    workflow_dispatch: null,
  });
  expect(workflow["permissions"]).toStrictEqual({ contents: "read" });
  const jobs = record(workflow["jobs"]);
  expect(Object.keys(jobs)).toEqual(["analyze"]);
  const job = record(jobs["analyze"]);
  expect(Object.keys(job).sort()).toEqual(
    ["name", "runs-on", "timeout-minutes", "permissions", "strategy", "steps"].sort(),
  );
  expect(job["runs-on"]).toBe("ubuntu-24.04");
  expect(job["timeout-minutes"]).toBe(20);
  expect(job["permissions"]).toStrictEqual({
    contents: "read",
    "security-events": "write",
  });
  expect(job["strategy"]).toStrictEqual({
    "fail-fast": false,
    matrix: { language: ["javascript-typescript", "actions"] },
  });
  const steps = job["steps"];
  assert(Array.isArray(steps) && steps.length === 3);
  const [checkout, init, analyze] = steps.map(record);
  assert(checkout !== undefined && init !== undefined && analyze !== undefined);
  for (const step of [checkout, init, analyze]) {
    expect(Object.keys(step).sort()).toEqual(["name", "uses", "with"]);
    expect(step["uses"]).toMatch(/@[0-9a-f]{40}$/u);
  }
  expect(checkout["uses"]).toMatch(/^actions\/checkout@/u);
  expect(checkout["with"]).toStrictEqual({ "persist-credentials": false });
  expect(init["uses"]).toMatch(/^github\/codeql-action\/init@/u);
  expect(analyze["uses"]).toMatch(/^github\/codeql-action\/analyze@/u);
  expect(String(init["uses"]).split("@")[1]).toBe(String(analyze["uses"]).split("@")[1]);
  expect(init["with"]).toStrictEqual({
    languages: matrixExpression,
    "build-mode": "none",
    queries: "security-extended",
    "dependency-caching": false,
    "trap-caching": false,
  });
  expect(analyze["with"]).toStrictEqual({
    category: "/language:" + matrixExpression,
    "upload-database": false,
    "wait-for-processing": true,
  });
}

const mutations = [
  ["privileged PR trigger", "pull_request:", "pull_request_target:"],
  ["wrong push branch", "branches: [main]", "branches: [experimental]"],
  ["omitted scheduled checks", '  schedule:\n    - cron: "23 7 * * 2"\n', ""],
  ["workflow write authority", "  contents: read", "  contents: write"],
  [
    "extra job permission",
    "      security-events: write",
    "      security-events: write\n      contents: write",
  ],
  ["silent job skip", "    runs-on: ubuntu-24.04", "    if: false\n    runs-on: ubuntu-24.04"],
  [
    "ignored failure",
    "    timeout-minutes: 20",
    "    continue-on-error: true\n    timeout-minutes: 20",
  ],
  ["removed deadline", "    timeout-minutes: 20\n", ""],
  ["missing Actions scan", "[javascript-typescript, actions]", "[javascript-typescript]"],
  ["persisted checkout token", "persist-credentials: false", "persist-credentials: true"],
  [
    "mutable action reference",
    "github/codeql-action/init@33d7b85da1a04171e211befe2c739303b9a4c066",
    "github/codeql-action/init@v4",
  ],
  ["wrong build mode", "build-mode: none", "build-mode: manual"],
  ["reduced queries", "queries: security-extended", "queries: default"],
  [
    "unreviewed source filter",
    "queries: security-extended",
    'queries: security-extended\n          config: \'{"paths-ignore":["src/**"]}\'',
  ],
  ["new extractor cache", "trap-caching: false", "trap-caching: true"],
  ["database upload", "upload-database: false", "upload-database: true"],
  ["unprocessed result upload", "wait-for-processing: true", "wait-for-processing: false"],
  [
    "skipped queries",
    "wait-for-processing: true",
    "wait-for-processing: true\n          skip-queries: true",
  ],
  [
    "disabled SARIF upload",
    "wait-for-processing: true",
    "wait-for-processing: true\n          upload: never",
  ],
  ["executable project step", "    steps:\n", "    steps:\n      - run: pnpm install\n"],
] as const;

describe("CodeQL workflow contract", () => {
  it("scans application sources and Actions without privileged project execution", async () => {
    assertPolicy(parse(await readFile(workflowURL, "utf8")) as unknown);
  });

  it.each(mutations)("rejects %s", async (_name, original, replacement) => {
    const source = await readFile(workflowURL, "utf8");
    expect(source).toContain(original);
    expect(() => assertPolicy(parse(source.replace(original, replacement)) as unknown)).toThrow();
  });
});
